        fontLink.href = 'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap';
        document.head.appendChild(fontLink);

        // ── Inject global CSS (replaces index.css which Flow cannot import) ──
        if (!document.getElementById('xray-injected-styles')) {
            const style = document.createElement('style');
            style.id = 'xray-injected-styles';
            style.textContent = `\n                :root {\n                    --surface: #080808; --surface-raised: #1c1c1c; --surface-overlay: #363636;\n                    --border: #404040; --border-dim: #2c2c2c;\n                    --text: #f8f8f8; --text-muted: #dcdcdc; --text-dim: #aaaaaa;\n                    --accent: #f0f0f0; --accent-muted: #505050;\n                    --error: #f87171; --green: #4ade80; --pink: #f472b6;\n                    --orange: #fb923c; --blue: #60a5fa; --purple: #c084fc;\n                    background-color: var(--surface); color: var(--text);\n                    --tint-character: oklch(48% 0.191 21.5);\n                    --tint-feedback: oklch(38% 0.172 232);\n                    --tint-prompt: oklch(33% 0.134 172);\n                }\n                .tint-character { --tint: var(--tint-character); --panel-surface: oklch(from var(--tint) 0.14 calc(c*0.12) h); --panel-surface-mid: oklch(from var(--tint) 0.18 calc(c*0.16) h); --panel-surface-alt: oklch(from var(--tint) 0.28 calc(c*0.35) h); --panel-border: oklch(from var(--tint) 0.36 calc(c*0.22) h); --panel-border-dim: oklch(from var(--tint) 0.24 calc(c*0.14) h); --panel-text: oklch(from var(--tint) 0.97 calc(c*0.06) h); --panel-text-muted: oklch(from var(--tint) 0.87 calc(c*0.10) h); --panel-text-dim: oklch(from var(--tint) 0.68 calc(c*0.14) h); --panel-accent: oklch(from var(--tint) 0.78 calc(c*0.55) h); }\n                .tint-feedback { --tint: var(--tint-feedback); --panel-surface: oklch(from var(--tint) 0.14 calc(c*0.12) h); --panel-surface-mid: oklch(from var(--tint) 0.18 calc(c*0.16) h); --panel-surface-alt: oklch(from var(--tint) 0.26 calc(c*0.35) h); --panel-border: oklch(from var(--tint) 0.36 calc(c*0.22) h); --panel-border-dim: oklch(from var(--tint) 0.24 calc(c*0.14) h); --panel-text: oklch(from var(--tint) 0.97 calc(c*0.06) h); --panel-text-muted: oklch(from var(--tint) 0.87 calc(c*0.10) h); --panel-text-dim: oklch(from var(--tint) 0.68 calc(c*0.14) h); --panel-accent: oklch(from var(--tint) 0.78 calc(c*0.55) h); }\n                .tint-prompt { --tint: var(--tint-prompt); --panel-surface: oklch(from var(--tint) 0.14 calc(c*0.12) h); --panel-surface-mid: oklch(from var(--tint) 0.18 calc(c*0.16) h); --panel-surface-alt: oklch(from var(--tint) 0.28 calc(c*0.35) h); --panel-border: oklch(from var(--tint) 0.36 calc(c*0.22) h); --panel-border-dim: oklch(from var(--tint) 0.24 calc(c*0.14) h); --panel-text: oklch(from var(--tint) 0.97 calc(c*0.06) h); --panel-text-muted: oklch(from var(--tint) 0.87 calc(c*0.10) h); --panel-text-dim: oklch(from var(--tint) 0.68 calc(c*0.14) h); --panel-accent: oklch(from var(--tint) 0.78 calc(c*0.55) h); }\n                html, body, #root { margin:0; padding:0; width:100%; height:100%; background:var(--surface); overflow:hidden; }\n                body { font-family:'Inter',system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif; font-size:13px; line-height:1.5; -webkit-font-smoothing:antialiased; -moz-osx-font-smoothing:grayscale; }\n                * { scrollbar-width:thin; scrollbar-color:var(--panel-border-dim,var(--border-dim)) transparent; }\n                ::-webkit-scrollbar { width:3px; height:3px; }\n                ::-webkit-scrollbar-track { background:transparent; }\n                ::-webkit-scrollbar-thumb { background:var(--panel-border-dim,var(--border-dim)); border-radius:3px; }\n                ::-webkit-scrollbar-thumb:hover { background:var(--panel-text-dim,var(--text-dim)); }\n                ::selection { background:var(--accent); color:white; }\n                .t-body { font-size:13px; line-height:1.5; font-weight:400; color:var(--panel-text-muted,var(--text-muted)); }\n                .t-title { font-size:13px; line-height:1.5; font-weight:500; color:var(--panel-text,var(--text)); }\n                .t-label { font-size:13px; line-height:1.3; font-weight:500; color:var(--panel-text-dim,var(--text-dim)); }\n                .t-brief { font-size:13px; line-h