id var(--panel-border-dim,var(--border)); background:var(--panel-surface-mid,var(--surface-raised)); flex-shrink:0; }\n                .feedback-grid { display:grid; grid-template-columns:1fr; gap:8px; }\n                @container (min-width:500px) { .feedback-grid { grid-template-columns:1fr 1fr; } }\n                .character-media-brief { display:flex; flex-direction:column; flex:5; min-height:0; overflow:hidden; }\n                .character-media { border-bottom:1px solid var(--panel-border-dim,var(--border)); }\n                .character-brief { overflow-y:auto; border-bottom:1px solid var(--panel-border-dim,var(--border)); }\n                .character-insights { flex:2; overflow-y:auto; min-height:0; }\n                .character-content--landscape .character-media { flex:5; min-height:100px; }\n                .character-content--landscape .character-brief { flex:3; min-height:80px; }\n                .character-content--portrait .character-media-brief { flex-direction:row; }\n                .character-content--portrait .character-media { width:50%; min-width:160px; flex-shrink:0; border-bottom:none; border-right:1px solid var(--panel-border-dim,var(--border)); }\n                .character-content--portrait .character-brief { flex:1; min-height:0; overflow-y:auto; border-bottom:none; }\n                .edge-start-btn { background:var(--accent); color:#141414; border:none; border-radius:4px; padding:4px 12px; font-size:12px; font-weight:500; cursor:pointer; display:inline-flex; align-items:center; gap:5px; transition:filter 0.15s ease,transform 0.15s ease; }\n                .edge-start-btn:hover { filter:brightness(1.15); }\n                .edge-start-btn:active { transform:scale(0.96); }\n                .edge-start-btn:disabled { opacity:1; background:var(--surface-overlay); color:var(--text-dim); cursor:not-allowed; }\n                .edge-action-btn { background:var(--surface-raised); color:var(--text-muted); border:1px solid var(--border); border-radius:4px; padding:3px 10px; font-size:12px; font-weight:500; cursor:pointer; display:inline-flex; align-items:center; transition:all 0.15s ease; white-space:nowrap; }\n                .edge-action-btn:hover { background:var(--surface-overlay); border-color:var(--text-dim); color:var(--text); }\n                .edge-action-btn:active { transform:scale(0.96); }\n                .edge-action-btn:disabled { pointer-events:none; background:var(--surface-raised); color:var(--text-dim); border-color:var(--border-dim); }\n                .panel-action-btn { background:rgba(255,255,255,0.85); color:#141414; border:1px solid rgba(255,255,255,0.9); border-radius:4px; padding:4px 12px; font-size:12px; font-weight:600; cursor:pointer; display:inline-flex; align-items:center; gap:5px; transition:all 0.15s ease; white-space:nowrap; }\n                .panel-action-btn:hover { background:rgba(255,255,255,0.95); border-color:#fff; color:#000; }\n                .panel-action-btn:active { transform:scale(0.96); }\n                .panel-action-btn:disabled { opacity:0.4; pointer-events:none; }\n                .lightbox-overlay { z-index:9999 !important; }\n                .rendering-overlay { display:flex; align-items:center; justify-content:center; background:rgba(0,0,0,0.6); backdrop-filter:blur(8px); }\n                .rendering-shimmer { position:absolute; inset:0; background:linear-gradient(110deg,transparent 25%,rgba(255,255,255,0.04) 37%,rgba(255,255,255,0.08) 50%,rgba(255,255,255,0.04) 63%,transparent 75%); background-size:300% 100%; animation:shimmer-sweep 6s ease-in-out infinite; }\n                @keyframes shimmer-sweep { 0% { background-position:200% 0; } 100% { background-position:-200% 0; } }\n            `;
            document.head.appendChild(style);
