// ---------------------------------------------------------------------------
// Error Boundary
// ---------------------------------------------------------------------------

interface ErrorBoundaryState {
    hasError: boolean;
    error: Error | null;
}

class ErrorBoundary extends Component<{ children: ReactNode }, ErrorBoundaryState> {
    constructor(props: { children: ReactNode }) {
        super(props);
        this.state = { hasError: false, error: null };
    }

    static getDerivedStateFromError(error: Error): ErrorBoundaryState {
        return { hasError: true, error };
    }

    componentDidCatch(error: Error, info: React.ErrorInfo) {
        console.error('ErrorBoundary caught:', error, info);
    }

    render() {
        if (this.state.hasError) {
            return (
                <div className="min-h-screen bg-zinc-950 flex items-center justify-center p-6">
                    <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-8 max-w-md text-center space-y-4">
                        <h2 className="text-xl font-bold text-white">Something went wrong</h2>
                        <p className="text-sm text-zinc-500 leading-relaxed">
                            {this.state.error?.message || 'An unexpected error occurred.'}
                        </p>
                        <button
                            onClick={() => {
                                this.setState({ hasError: false, error: null });
                                window.location.reload();
                            }}
                            className="px-5 py-2.5 bg-white text-black rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-zinc-200 transition-all"
                        >
                            Reload
                        </button>
                    </div>
                </div>
            );
        }
        return this.props.children;
    }
}

// ---------------------------------------------------------------------------
// App
// ---------------------------------------------------------------------------

export default function App() {
    useGlobalStyles();

    return (
        <ErrorBoundary>
            <div className="min-h-screen bg-zinc-950 selection:bg-white selection:text-black">
                <ExecutiveRoom />
            </div>
        </ErrorBoundary>
    );
}

import React, { useState, useRef, useEffect } from 'react';

interface CharacterBriefProps {
    backstory: string;
    highlightSegments: string[];
    onBackstoryChange: (text: string) => void;
    onClearHighlights: () => void;
}

export const CharacterBrief: React.FC<CharacterBriefProps> = ({
    backstory,
    highlightSegments,
    onBackstoryChange,
    onClearHighlights,
}) => {
    const [editing, setEditing] = useState(false);
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    useEffect(() => {
        if (textareaRef.current) {
            const el = textareaRef.current;
            el.style.height = '0';
            el.style.height = `${Math.max(60, el.scrollHeight)}px`;
        }
    }, [backstory, editing]);

    const renderHighlightedBrief = () => {
        if (!highlightSegments || highlightSegments.length === 0) return backstory;
        const parts: (string | React.ReactNode)[] = [];
        let remaining = backstory;
        let keyIdx = 0;
        for (const seg of highlightSegments) {
            const idx = remaining.toLowerCase().indexOf(seg.toLowerCase());
            if (idx !== -1) {
                if (idx > 0) parts.push(remaining.substring(0, idx));
                parts.push(
                    <mark key={keyIdx++} style={{
                        background: 'rgba(59,130,246,0.15)',
                        color: 'var(--accent)',
                        borderRadius: '2px',
                        padding: '0 2px'
                    }}>
                        {remaining.substring(idx, idx + seg.length)}
                    </mark>
                );
                remaining = remaining.substring(idx + seg.length);
            }
        }
        if (remaining) parts.push(remaining);
        return parts;
    };

    return (
        <div>
            <span className="t-label flex items-center gap-1 mb-2">
                Brief
            </span>

            {editing ? (
                <textarea
                    ref={textareaRef}
                    value={backstory}
                    onChange={(e) => onBackstoryChange(e.target.value)}
                    onBlur={() => setEditing(false)}
                    autoFocus
                    placeholder="Describe this character..."
                    className="w-full min-h-[60px] bg-transparent t-brief focus:ring-0 outline-none resize-none border-none"
                />
            ) : (
                <div
                    onClick={() => { setEditing(true); onClearHighlights(); }}
                    className="w-full t-brief cursor-text whitespace-pre-wrap min-h-[60px]"
                >
                    {backstory ? renderHighlightedBrief() : (
                        <span style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>
                            Describe this character...
                        </span>
                    )}
                </div>
            )}
        </div>
    );
};

import React, { useRef, useState, useEffect } from 'react';
import { Loader2 } from 'lucide-react';

interface CharacterInsightsProps {
    wardrobeSummary: string;
    personalitySummary: string;
    analyzing: boolean;
}

/**
 * Reveals text in word chunks when `text` changes to a new non-empty value.
 * Set `enabled` to false to skip animation (e.g. navigating image history).
 * When `delayMs` > 0, waits before starting (used to sequence columns).
 */
function useTypewriter(
    text: string,
    enabled: boolean,
    wordsPerTick = 3,
    intervalMs = 30,
    delayMs = 0,
) {
    const [displayed, setDisplayed] = useState(text);
    const [isTyping, setIsTyping] = useState(false);
    const prevText = useRef(text);
    const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
    const delayRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => {
        // Only animate when text actually changes to a new non-empty value
        if (text === prevText.current) return;
        const wasEmpty = !prevText.current;
        prevText.current = text;

        // Clean up any running animation
        if (timerRef.current) clearInterval(timerRef.current);
        if (delayRef.current) clearTimeout(delayRef.current);

        if (!text) {
            setDisplayed('');
            setIsTyping(false);
            return;
        }

        // Skip animation if disabled (e.g. navigating history)
        if (!enabled) {
            setDisplayed(text);
            setIsTyping(false);
            return;
        }

        // Split into words, reveal several at a time
        const words = text.split(' '); // split on spaces
        let wordIndex = 0;

        const startTyping = () => {
            setDisplayed('');
            setIsTyping(true);

            timerRef.current = setInterval(() => {
                wordIndex = Math.min(wordIndex + wordsPerTick, words.length);
                setDisplayed(words.slice(0, wordIndex).join(' '));

                if (wordIndex >= words.length) {
                    if (timerRef.current) clearInterval(timerRef.current);
                    timerRef.current = null;
                    setIsTyping(false);
                }
            }, intervalMs);
        };

        if (delayMs > 0) {
            setDisplayed('');
            delayRef.current = setTimeout(startTyping, delayMs);
        } else {
            startTyping();
        }

        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
            if (delayRef.current) clearTimeout(delayRef.current);
        };
    }, [text, enabled, wordsPerTick, intervalMs, delayMs]);

    return { displayed, isTyping };
}

export const CharacterInsights: React.FC<CharacterInsightsProps> = ({
    wardrobeSummary,
    personalitySummary,
    analyzing,
}) => {
    // Estimate how long wardrobe typing takes so psychology starts after
    const wardrobeWords = wardrobeSummary ? wardrobeSummary.split(' ').filter(w => w.length > 0).length : 0;
    const wardrobeDuration = Math.ceil(wardrobeWords / 3) * 30 + 100; // ticks * interval + buffer

    const wardrobe = useTypewriter(wardrobeSummary, analyzing, 3, 30, 0);
    const personality = useTypewriter(personalitySummary, analyzing, 3, 30, wardrobeDuration);

    return (
        <div className="grid grid-cols-2 h-full" style={{ minHeight: 0 }}>
            <div className="p-3 overflow-y-auto" style={{ borderRight: '1px solid var(--panel-border-dim, var(--border))', minHeight: 0 }}>
                <span className="t-label flex items-center gap-1 mb-1">
                    Wardrobe
                </span>
                {analyzing && !wardrobeSummary ? (
                    <div className="flex items-center gap-1" style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>
                        <Loader2 className="w-3 h-3 animate-spin" />
                    </div>
                ) : (
                    <p className="t-body">
                        {wardrobe.displayed || <span style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>—</span>}
                        {wardrobe.isTyping && <span className="typewriter-cursor">▎</span>}
                    </p>
                )}
            </div>

            <div className="p-3 overflow-y-auto" style={{ minHeight: 0 }}>
                <span className="t-label flex items-center gap-1 mb-1">
                    Psychology
                </span>
                {analyzing && !personalitySummary ? (
                    <div className="flex items-center gap-1" style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>
                        <Loader2 className="w-3 h-3 animate-spin" />
                    </div>
                ) : (
                    <p className="t-body">
                        {personality.displayed || <span style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>—</span>}
                        {personality.isTyping && <span className="typewriter-cursor">▎</span>}
                    </p>
                )}
            </div>
        </div>
    );
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
