export const ExecutiveRoom: React.FC = () => {
    const {
        state, analyzing, visualizing, adoptingId, regeneratingId, craftingPrompt, error, actions,
    } = useCharacterState();

    const hasStartedRef = useRef(false);
    if (state.activeFeedback.length > 0 || analyzing || visualizing) {
        hasStartedRef.current = true;
    }
    const hasStarted = hasStartedRef.current;
    const busy = analyzing || visualizing || craftingPrompt;
    const canStart = state.initialBackstory.trim().length > 0 || state.imageHistory.length > 0;
    const hasPrompt = !!state.pendingImagePrompt;

    // Auto-dismiss error toast after 5s
    const [dismissedError, setDismissedError] = useState<string | null>(null);
    useEffect(() => {
        if (error && error !== dismissedError) {
            setDismissedError(null);
            const timer = setTimeout(() => setDismissedError(error), 5000);
            return () => clearTimeout(timer);
        }
    }, [error, dismissedError]);
    const visibleError = error && error !== dismissedError ? error : null;

    // Track if the user has ever crafted a prompt (first loop only)
    const [promptRevealed, setPromptRevealed] = useState(false);
    useEffect(() => {
        if (!promptRevealed && (craftingPrompt || state.pendingImagePrompt)) {
            setPromptRevealed(true);
        }
    }, [craftingPrompt, state.pendingImagePrompt, promptRevealed]);

    // ── Cmd+Enter → kickoff ──
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
                e.preventDefault();
                if (canStart && !busy) actions.kickoff();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [canStart, busy, actions]);

    // ── Resizable layout state ──
    const [leftWidthPct, setLeftWidthPct] = useState(50); // % of viewport
    const [charHeightPct, setCharHeightPct] = useState(70); // % of left column

    const containerRef = useRef<HTMLDivElement>(null);
    const draggingRef = useRef<'vertical' | 'horizontal' | null>(null);

    const onMouseDown = useCallback((axis: 'vertical' | 'horizontal') => {
        draggingRef.current = axis;
        document.body.style.cursor = axis === 'vertical' ? 'col-resize' : 'row-resize';
        document.body.style.userSelect = 'none';
    }, []);

    useEffect(() => {
        const onMouseMove = (e: MouseEvent) => {
            if (!draggingRef.current || !containerRef.current) return;
            const rect = containerRef.current.getBoundingClientRect();

            if (draggingRef.current === 'vertical') {
                const pct = ((e.clientX - rect.left) / rect.width) * 100;
                setLeftWidthPct(Math.min(Math.max(pct, 25), 75));
            } else {
                const pct = ((e.clientY - rect.top) / rect.height) * 100;
                setCharHeightPct(Math.min(Math.max(pct, 20), 85));
            }
        };

        const onMouseUp = () => {
            if (draggingRef.current) {
                draggingRef.current = null;
                document.body.style.cursor = '';
                document.body.style.userSelect = '';
            }
        };

        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        return () => {
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
        };
    }, []);

    return (
        <div ref={containerRef} className="studio-layout">
            {/* ── Left Column: Character + Prompt ── */}
            <div className="studio-left" style={{ width: `${leftWidthPct}%` }}>
                <div style={{ height: `${charHeightPct}%`, minHeight: 200 }}>
                    <CharacterPanel
                        state={state}
                        analyzing={analyzing}
                        visualizing={visualizing}
                        busy={busy}
                        hasStarted={hasStarted}
                        canStart={canStart}
                        actions={actions}
                    />
                </div>

                {/* Horizontal divider */}
                <div
                    className="studio-divider studio-divider--horizontal"
                    onMouseDown={() => onMouseDown('horizontal')}
                />

                <div style={{ flex: 1, minHeight: 120 }} className={promptRevealed ? 'panel-reveal panel-reveal--visible' : 'panel-reveal'}>
                    <PromptPanel
                        pendingPrompt={state.pendingImagePrompt}
                        visualizing={visualizing}
                        craftingPrompt={craftingPrompt}
                        hasPrompt={hasPrompt}
                        onGenerate={actions.confirmImageGeneration}
                        actions={actions}
                    />
                </div>
            </div>

            {/* Vertical divider */}
            <div
                className="studio-divider studio-divider--vertical"
                onMouseDown={() => onMouseDown('vertical')}
            />

            {/* ── Right Column: Feedback + Instructions ── */}
            <div className="studio-right" style={{ flex: 1, position: 'relative' }}>
                {/* Onboarding instructions — visible until feedback fades in */}
                <div className="onboarding-instructions">
                    <div className="onboarding-steps">
                        <p className="onboarding-title">How It Works</p>
                        <div className="onboarding-step">
                            <span className="step-number">1</span>
                            <p>Upload your character portrait and/or write their backstory.</p>
                        </div>
                        <div className="onboarding-step">
                            <span className="step-number">2</span>
                            <p>Hit <strong>Start</strong> to get opinionated feedback from Gemini.</p>
                        </div>
                        <div className="onboarding-step">
                            <span className="step-number">3</span>
                            <p>Choose the suggestions you like. The app will craft a prompt you can use to refine your portrait.</p>
                        </div>
                        <p className="onboarding-repeat">Repeat until your character feels right.</p>
                    </div>
                </div>

                {/* Feedback panel — fades in over instructions */}
                <div className={hasStarted ? 'panel-reveal panel-reveal--visible' : 'panel-reveal'}
                    style={{ position: 'relative', zIndex: 1, height: '100%' }}>
                    <FeedbackPanel
                        activeFeedback={state.activeFeedback}
                        analyzing={analyzing}
                        visualizing={visualizing}
                        busy={analyzing || visualizing}
                        hasStarted={hasStarted}
                        regeneratingId={regeneratingId}
                        adoptingId={adoptingId}
                        craftingPrompt={craftingPrompt}
                        onCraft={actions.prepareImagePrompt}
                        actions={actions}
                    />
                </div>
            </div>

            {/* Error toast — auto-dismisses after 5s, click to dismiss */}
            {visibleError && (
                <div className="fixed bottom-4 left-1/2 -translate-x-1/2 panel px-4 py-2 animate-fade-in cursor-pointer"
                    style={{ zIndex: 9999, background: 'rgba(248,113,113,0.15)', borderColor: 'var(--error)' }}
                    onClick={() => setDismissedError(visibleError)}>
                    <p className="t-label" style={{ color: 'var(--error)' }}>{visibleError}</p>
                </div>
            )}
        </div>
    );
};

import React, { useState } from 'react';
import { Feedback } from '../types';
import { Send, RefreshCw, Loader2, Check } from 'lucide-react';

interface FeedbackCardProps {
    feedback: Feedback;
    onAnswer: (answer: string) => void;
    onRegenerate: () => void;
    disabled?: boolean;
    isRegenerating?: boolean;
    isAdopting?: boolean;
}

const CATEGORY_COLORS: Record<string, string> = {
    wardrobe: 'var(--blue)',
    style: 'var(--pink)',
    color: 'var(--orange)',
    lore: 'var(--green)',
    narrative: 'var(--purple)',
};

export const FeedbackCard: React.FC<FeedbackCardProps> = ({
    feedback, onAnswer, onRegenerate, disabled, isRegenerating, isAdopting,
}) => {
    const [customAnswer, setCustomAnswer] = useState('');
    const suggestions = feedback.suggestions || [];
    const category = feedback.category || 'style';
    const color = CATEGORY_COLORS[category] || 'var(--text-dim)';
    const busy = disabled || isRegenerating || isAdopting;
    const selected = feedback.answeredWith || [];
    const hasSelections = selected.length > 0;

    return (
        <div className="panel p-3 space-y-2 transition-all"
            style={{
                ...(isAdopting ? { opacity: 0.5 } : {}),
            }}>

            {/* Category + status */}
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-1.5">
                    <span className="t-label" style={{ color }}>{category.charAt(0).toUpperCase() + category.slice(1)}</span>
                    {hasSelections && <Check className="w-3 h-3" style={{ color }} />}
                </div>
                <div className="flex items-center gap-1">
                    {isAdopting && <Loader2 className="w-3 h-3 animate-spin" style={{ color: 'var(--accent)' }} />}
                    <button onClick={onRegenerate} disabled={busy}
                        className="p-1 rounded transition-colors feedback-icon-btn">
                        <RefreshCw className={`w-3 h-3 ${isRegenerating ? 'animate-spin' : ''}`} />
                    </button>
                </div>
            </div>

            {/* Insight */}
            <p className="t-title">
                {isRegenerating
                    ? <span className="animate-pulse" style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>Thinking...</span>
                    : feedback.insight}
            </p>

            {/* Suggestions — toggle multi-select */}
            <div className="space-y-1">
                {suggestions.map((s, idx) => {
                    const isSelected = selected.includes(s.text);
                    return (
                        <button key={idx} disabled={busy}
                            onClick={() => onAnswer(s.text)}
                            className={`group w-full text-left px-2 py-1.5 rounded transition-all suggestion-btn`}
                            style={{
                                background: 'var(--panel-surface, var(--surface))',
                                border: isSelected
                                    ? `1px solid ${color}`
                                    : '1px solid var(--panel-border-dim, var(--border-dim))',
                            }}>
                            <div className="t-body" style={{ color: 'var(--panel-text, var(--text))' }}>{s.text}</div>
                            {s.reasoning && <div className="t-body mt-0.5" style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>{s.reasoning}</div>}
                        </button>
                    );
                })}

                {/* Custom answer */}
                <div className="relative">
                    <input type="text"
                        value={customAnswer}
                        onChange={(e) => setCustomAnswer(e.target.value)}
                        placeholder="Custom answer..."
                        disabled={busy}
                        className="custom-answer-input w-full rounded px-2 py-1.5 t-body outline-none border"
                        onKeyDown={(e) => e.key === 'Enter' && customAnswer.trim() && onAnswer(customAnswer)} />
                    <button onClick={() => customAnswer.trim() && onAnswer(customAnswer)}
                        disabled={busy || !customAnswer.trim()}
                        className="absolute right-1.5 top-1/2 -translate-y-1/2 p-1 disabled:opacity-20"
                        style={{ color: 'var(--panel-accent, var(--accent))' }}>
                        <Send className="w-3 h-3" />
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { createPortal } from 'react-dom';
import { CharacterImage } from '../types';
import {
    Upload, ChevronLeft, ChevronRight,
    Download, X, Maximize2, RefreshCw,
} from 'lucide-react';

/* ── Lightbox (rendered via portal to body) ── */

interface LightboxProps {
    images: CharacterImage[];
    currentIndex: number;
    onClose: () => void;
    onNavigate: (index: number) => void;
}

const Lightbox: React.FC<LightboxProps> = ({ images, currentIndex, onClose, onNavigate }) => {
    const handleKeyDown = useCallback((e: KeyboardEvent) => {
        if (e.key === 'Escape') onClose();
        if (e.key === 'ArrowLeft' && currentIndex > 0) onNavigate(currentIndex - 1);
        if (e.key === 'ArrowRight' && currentIndex < images.length - 1) onNavigate(currentIndex + 1);
    }, [currentIndex, images.length, onClose, onNavigate]);

    useEffect(() => {
        document.addEventListener('keydown', handleKeyDown);
        document.body.style.overflow = 'hidden';
        return () => { document.removeEventListener('keydown', handleKeyDown); document.body.style.overflow = ''; };
    }, [handleKeyDown]);

    const current = images[currentIndex];
    if (!current) return null;

    return createPortal(
        <div className="fixed inset-0 flex items-center justify-center"
            style={{ background: 'rgba(0,0,0,0.92)', zIndex: 99999 }} onClick={onClose}>
            <button onClick={onClose} className="absolute top-4 right-4 p-2 rounded"
                style={{ background: 'var(--surface-raised)', color: 'var(--text-muted)', zIndex: 10 }}>
                <X className="w-5 h-5" />
            </button>
            <div className="absolute top-4 left-1/2 -translate-x-1/2 px-3 py-1 rounded t-label"
                style={{ background: 'var(--surface-raised)', zIndex: 10 }}>
                {currentIndex + 1} / {images.length}
            </div>
            {currentIndex > 0 && (
                <button onClick={(e) => { e.stopPropagation(); onNavigate(currentIndex - 1); }}
                    className="absolute left-4 top-1/2 -translate-y-1/2 p-3 rounded"
                    style={{ background: 'var(--surface-raised)', color: 'var(--text)', zIndex: 10 }}>
                    <ChevronLeft className="w-6 h-6" />
                </button>
            )}
            {currentIndex < images.length - 1 && (
                <button onClick={(e) => { e.stopPropagation(); onNavigate(currentIndex + 1); }}
                    className="absolute right-4 top-1/2 -translate-y-1/2 p-3 rounded"
                    style={{ background: 'var(--surface-raised)', color: 'var(--text)', zIndex: 10 }}>
                    <ChevronRight className="w-6 h-6" />
                </button>
            )}
            <img src={current.dataUrl} alt={`Revision ${currentIndex + 1}`}
                className="max-w-[90vw] max-h-[85vh] object-contain rounded animate-fade-in"
                onClick={(e) => e.stopPropagation()} />
        </div>,
        document.body
    );
};

/* ── ImagePanel ── */

interface ImagePanelProps {
    imageHistory: CharacterImage[];
    currentImageIndex: number;
    visualizing: boolean;
    onNavImage: (index: number) => void;
    onSaveImage: () => void;
    onUploadImage: () => void;
    onStartOver: () => void;
    onRegenerate?: () => void;
}

export const ImagePanel: React.FC<ImagePanelProps> = ({
    imageHistory, currentImageIndex, visualizing,
    onNavImage, onSaveImage, onUploadImage, onStartOver, onRegenerate,
}) => {
    const [lightboxOpen, setLightboxOpen] = useState(false);
    const [lightboxIndex, setLightboxIndex] = useState(0);
    const currentImage = imageHistory[currentImageIndex];

    const openLightbox = () => {
        if (currentImage) { setLightboxIndex(currentImageIndex); setLightboxOpen(true); }
    };

    const canGoLeft = currentImageIndex > 0;
    const canGoRight = currentImageIndex < imageHistory.length - 1;

    return (
        <div className="flex flex-col h-full" style={{ background: 'var(--panel-surface, var(--surface))' }}>
            {/* Image area */}
            <div className="relative flex items-center justify-center overflow-hidden flex-1 min-h-0">
                {currentImage ? (
                    <>
                        <img src={currentImage.dataUrl} className="w-full h-full object-contain cursor-pointer"
                            alt="Character" onClick={openLightbox} />
                    </>
                ) : (
                    <button onClick={onUploadImage}
                        className="flex flex-col items-center justify-center w-full h-full cursor-pointer"
                        style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>
                        <Upload className="w-8 h-8 opacity-30" />
                        <p className="t-label mt-2">Upload an image</p>
                    </button>
                )}

                {/* Google Flow-style gradient loading overlay */}
                {visualizing && (
                    <div className="absolute inset-0 z-20 rendering-overlay">
                        <div className="rendering-shimmer" />
                    </div>
                )}
            </div>

            {/* Bottom bar — nav + controls */}
            <div className="flex items-center justify-between px-3 py-1.5 shrink-0"
                style={{ borderTop: '1px solid var(--panel-border-dim, var(--border))', background: 'var(--panel-surface-mid, var(--surface-raised))' }}>
                <div className="flex items-center gap-1">
                    <button disabled={!canGoLeft}
                        onClick={() => onNavImage(currentImageIndex - 1)}
                        className="p-0.5 rounded disabled:opacity-20"
                        style={{ color: 'var(--panel-text-muted, var(--text-muted))' }}>
                        <ChevronLeft className="w-3.5 h-3.5" />
                    </button>
                    <span className="t-label px-0.5" style={{ color: 'var(--panel-text-dim, var(--text-dim))', minWidth: '28px', textAlign: 'center' }}>
                        {imageHistory.length > 0 ? `${currentImageIndex + 1}/${imageHistory.length}` : '—'}
                    </span>
                    <button disabled={!canGoRight}
                        onClick={() => onNavImage(currentImageIndex + 1)}
                        className="p-0.5 rounded disabled:opacity-20"
                        style={{ color: 'var(--panel-text-muted, var(--text-muted))' }}>
                        <ChevronRight className="w-3.5 h-3.5" />
                    </button>
                </div>

                <div className="flex items-center gap-2">
                    <button onClick={onStartOver} className="p-1 rounded"
                        style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}
                        title="Start over with new image">
                        <Upload className="w-3 h-3" />
                    </button>
                    {currentImage && (
                        <>
                            <button onClick={openLightbox} className="p-1 rounded" style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>
                                <Maximize2 className="w-3 h-3" />
                            </button>
                            {onRegenerate && (
                                <button onClick={onRegenerate} disabled={visualizing}
                                    className="p-1 rounded disabled:opacity-20" style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}
                                    title="Regenerate image">
                                    <RefreshCw className="w-3 h-3" />
                                </button>
                            )}
                            <button onClick={onSaveImage} className="p-1 rounded" style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>
                                <Download className="w-3 h-3" />
                            </button>
                        </>
                    )}
                </div>
            </div>

            {lightboxOpen && (
                <Lightbox images={imageHistory} currentIndex={lightboxIndex}
                    onClose={() => setLightboxOpen(false)}
                    onNavigate={(idx) => { setLightboxIndex(idx); onNavImage(idx); }} />
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { ImagePanel } from '../ImagePanel';
import { CharacterBrief } from '../CharacterBrief';
import { CharacterInsights } from '../CharacterInsights';
import { Loader2 } from 'lucide-react';
import type { CharacterState, CharacterActions } from '../../types';

interface CharacterPanelProps {
    state: CharacterState;
    analyzing: boolean;
    visualizing: boolean;
    busy: boolean;
    hasStarted: boolean;
    canStart: boolean;
    actions: Pick<CharacterActions, 'navImage' | 'saveCurrentImage' | 'uploadImage' | 'startOver' | 'regenerateImage' | 'setBackstory' | 'clearHighlights' | 'kickoff'>;
}

export const CharacterPanel: React.FC<CharacterPanelProps> = ({
    state, analyzing, visualizing, busy, hasStarted, canStart, actions,
}) => {
    const isEmpty = !state.initialBackstory.trim() && state.imageHistory.length === 0;

    const label = analyzing
        ? 'Analyzing...'
        : hasStarted
            ? 'Get feedback'
            : 'Start';

    // Detect image aspect ratio to switch layout mode
    const [isPortrait, setIsPortrait] = useState(false);
    const currentImage = state.imageHistory[state.currentImageIndex];

    useEffect(() => {
        if (!currentImage?.dataUrl) {
            setIsPortrait(false);
            return;
        }
        const img = new Image();
        img.onload = () => {
            // Portrait or square = side-by-side layout
            setIsPortrait(img.naturalWidth <= img.naturalHeight);
        };
        img.src = currentImage.dataUrl;
    }, [currentImage?.dataUrl]);

    return (
        <div className="studio-panel tint-character">
            <div className="studio-panel-header">
                <span className="step-number">1</span>
                <span className="t-label">Character</span>
                {(analyzing || visualizing) && <Loader2 className="w-3 h-3 animate-spin" style={{ color: 'var(--panel-text-dim, var(--text-dim))' }} />}
                <button
                    className="panel-action-btn ml-auto"
                    onClick={actions.kickoff}
                    disabled={busy || !canStart}
                >
                    {label}
                </button>
            </div>

            <div className={`studio-panel-body ${isPortrait ? 'character-content--portrait' : 'character-content--landscape'}`}>
                {/* Image + Brief region */}
                <div className="character-media-brief">
                    <div className="character-media">
                        <ImagePanel
                            imageHistory={state.imageHistory}
                            currentImageIndex={state.currentImageIndex}
                            visualizing={visualizing}
                            onNavImage={actions.navImage}
                            onSaveImage={actions.saveCurrentImage}
                            onUploadImage={actions.uploadImage}
                            onStartOver={actions.startOver}
                            onRegenerate={actions.regenerateImage}
                        />
                    </div>

                    <div className="character-brief">
                        <div className="p-3">
                            <CharacterBrief
                                backstory={state.initialBackstory}
                                highlightSegments={state.highlightSegments}
                                onBackstoryChange={actions.setBackstory}
                                onClearHighlights={actions.clearHighlights}
                            />
                        </div>
                    </div>
                </div>

                {/* Insights — fade in after Start, container keeps fixed height */}
                <div className="character-insights">
                    <div className={hasStarted ? 'panel-reveal panel-reveal--visible' : 'panel-reveal'}
                        style={{ height: '100%', overflow: hasStarted ? 'visible' : 'hidden' }}>
                        <CharacterInsights
                            wardrobeSummary={state.wardrobeSummary}
                            personalitySummary={state.personalitySummary}
                            analyzing={analyzing}
                        />
                    </div>
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { FeedbackCard } from '../FeedbackCard';
import { Loader2 } from 'lucide-react';
import type { Feedback, CharacterActions } from '../../types';

interface FeedbackPanelProps {
    activeFeedback: Feedback[];
    analyzing: boolean;
    visualizing: boolean;
    busy: boolean;
    hasStarted: boolean;
    regeneratingId: string | null;
    adoptingId: string | null;
    craftingPrompt: boolean;
    onCraft: () => Promise<void>;
    actions: Pick<CharacterActions, 'adoptAnswer' | 'regenerateFeedback' | 'resetAnswers'>;
}

const AUTO_CRAFT_THRESHOLD = 2;

export const FeedbackPanel: React.FC<FeedbackPanelProps> = ({
    activeFeedback, analyzing, visualizing, busy, hasStarted,
    regeneratingId, adoptingId, craftingPrompt, onCraft, actions,
}) => {
    const loading = analyzing || visualizing;
    const answeredCount = activeFeedback.filter(f => f.answeredWith && f.answeredWith.length > 0).length;
    const totalCount = activeFeedback.length;
    const showProgress = totalCount > 0 && !loading && answeredCount < AUTO_CRAFT_THRESHOLD;

    return (
        <div className="studio-panel tint-feedback">
            <div className="studio-panel-header">
                <span className="step-number">2</span>
                <span className="t-label">Feedback</span>
                {loading && <Loader2 className="w-3 h-3 animate-spin" style={{ color: 'var(--panel-text-dim, var(--text-dim))' }} />}
                {showProgress && (
                    <span className="t-label" style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>
                        {answeredCount}/{AUTO_CRAFT_THRESHOLD}
                    </span>
                )}
                <div className="ml-auto flex items-center gap-2">
                    {totalCount > 0 && !loading && (
                        <button
                            onClick={actions.resetAnswers}
                            disabled={answeredCount === 0}
                            style={{
                                background: 'none',
                                border: 'none',
                                padding: '2px 6px',
                                fontSize: '11px',
                                fontWeight: 500,
                                cursor: answeredCount === 0 ? 'default' : 'pointer',
                                color: 'var(--panel-text-dim, var(--text-dim))',
                                opacity: answeredCount === 0 ? 0.35 : 1,
                                transition: 'opacity 0.15s ease',
                            }}
                        >
                            Reset
                        </button>
                    )}
                    <button
                        className="panel-action-btn"
                        onClick={onCraft}
                        disabled={craftingPrompt || !hasStarted || busy}
                    >
                        {craftingPrompt ? 'Writing prompt...' : 'Write prompt'}
                    </button>
                </div>
            </div>

            <div className="studio-panel-body p-2">
                {loading ? (
                    <div className="flex flex-col gap-2">
                        {[0, 1, 2].map((i) => (
                            <div key={i} className={`panel p-3 space-y-2.5 animate-skeleton stagger-${i + 1}`}>
                                <div className="h-3 w-20 rounded" style={{ background: 'var(--panel-surface-alt, var(--surface-overlay))' }} />
                                <div className="h-4 w-4/5 rounded" style={{ background: 'var(--panel-surface-alt, var(--surface-overlay))' }} />
                                <div className="space-y-1.5">
                                    <div className="h-8 rounded" style={{ background: 'var(--panel-surface, var(--surface))' }} />
                                    <div className="h-8 rounded" style={{ background: 'var(--panel-surface, var(--surface))' }} />
                                </div>
                            </div>
                        ))}
                    </div>
                ) : activeFeedback.length > 0 ? (
                    <div className="feedback-grid">
                        {activeFeedback.map((f) => (
                            <FeedbackCard key={f.id} feedback={f}
                                onAnswer={(ans) => actions.adoptAnswer(f.id, ans)}
                                onRegenerate={() => actions.regenerateFeedback(f.id)}
                                disabled={busy}
                                isRegenerating={regeneratingId === f.id}
                                isAdopting={adoptingId === f.id}
                            />
                        ))}
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center h-full gap-3 px-6" style={{ color: 'var(--panel-text-dim, var(--text-dim))' }}>
                        <p className="t-body text-center" style={{ lineHeight: '1.6' }}>
                            {hasStarted
                                ? 'All feedback addressed — craft a prompt to generate'
                                : 'Add an image or write a brief to start'}
                        </p>
                    </div>
                )}
            </div>
        </div>
    );
};

