import { CharacterState, CharacterAction } from '../types';

// ---------------------------------------------------------------------------
// Reducer
// ---------------------------------------------------------------------------

export function characterReducer(state: CharacterState, action: CharacterAction): CharacterState {
    switch (action.type) {
        case 'SET_FEEDBACK':
            return { ...state, activeFeedback: action.feedback };
        case 'ADD_IMAGE':
            return {
                ...state,
                imageHistory: [...state.imageHistory, action.image],
                currentImageIndex: state.imageHistory.length,
            };
        case 'NAV_IMAGE':
            return { ...state, currentImageIndex: action.index };
        case 'RESTORE_SNAPSHOT': {
            const snap = action.snapshot;
            return {
                ...state,
                initialBackstory: snap.brief,
                wardrobeSummary: snap.wardrobe,
                personalitySummary: snap.personality,
                highlightSegments: [],
            };
        }
        case 'UPDATE_BRIEF':
            return {
                ...state,
                initialBackstory: action.brief,
                highlightSegments: [...state.highlightSegments, ...action.highlights],
            };
        case 'REMOVE_FEEDBACK':
            return {
                ...state,
                activeFeedback: state.activeFeedback.filter((f) => !action.ids.includes(f.id)),
            };
        case 'ANSWER_FEEDBACK': {
            return {
                ...state,
                activeFeedback: state.activeFeedback.map((f) => {
                    if (f.id !== action.id) return f;
                    const prev = f.answeredWith || [];
                    // Toggle: remove if already selected, add if not
                    const has = prev.includes(action.answer);
                    const next = has ? prev.filter(a => a !== action.answer) : [...prev, action.answer];
                    return { ...f, answeredWith: next.length > 0 ? next : undefined };
                }),
            };
        }
        case 'RESET_ANSWERS':
            return {
                ...state,
                activeFeedback: state.activeFeedback.map(f => ({ ...f, answeredWith: undefined })),
            };
        case 'REPLACE_FEEDBACK':
            return {
                ...state,
                activeFeedback: state.activeFeedback.map((f) =>
                    f.id === action.oldId ? action.newFeedback : f
                ),
            };
        case 'SET_BACKSTORY':
            return { ...state, initialBackstory: action.backstory, highlightSegments: [] };
        case 'CLEAR_HIGHLIGHTS':
            return { ...state, highlightSegments: [] };
        case 'SET_SUMMARIES':
            return { ...state, wardrobeSummary: action.wardrobe, personalitySummary: action.personality };
        case 'SET_IMAGE_PROMPT':
            return { ...state, pendingImagePrompt: action.prompt };
        case 'CLEAR_IMAGE_PROMPT':
            return { ...state, pendingImagePrompt: null };
        case 'RESET':
            return { ...DEFAULT_STATE };
        default:
            return state;
    }
}

// ---------------------------------------------------------------------------
// Default initial state
// ---------------------------------------------------------------------------

export const DEFAULT_STATE: CharacterState = {
    initialBackstory: '',
    imageHistory: [],
    currentImageIndex: -1,
    activeFeedback: [],
    highlightSegments: [],
    wardrobeSummary: '',
    personalitySummary: '',
    pendingImagePrompt: null,
};

import { useReducer, useCallback, useState, useRef, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import {
    CharacterState,
    CharacterImage,
    Feedback,
    CharacterActions,
} from '../types';
import {
    getCharacterUpdate,
    reVisualizeCharacter,
    regenerateSingleFeedback,
    updateCharacterBrief,
    generateCharacterSummaries,
    craftImagePrompt,
    generateImageFromPrompt,
} from '../services/aiService';
import { characterReducer, DEFAULT_STATE } from './characterReducer';
import { createCharacterImage } from '../utils/image';

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

export function useCharacterState() {
    const [state, dispatch] = useReducer(characterReducer, DEFAULT_STATE);

    // Independent loading flags
    const [analyzing, setAnalyzing] = useState(false);
    const [visualizing, setVisualizing] = useState(false);
    const [adoptingId, setAdoptingId] = useState<string | null>(null);
    const [regeneratingId, setRegeneratingId] = useState<string | null>(null);
    const [craftingPrompt, setCraftingPrompt] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Always-fresh ref
    const stateRef = useRef(state);
    useEffect(() => {
        stateRef.current = state;
    }, [state]);

    // --- Internal helpers ---

    /**
     * Generate an image and dispatch ADD_IMAGE. Shared by kickoff, generateImage, regenerateImage.
     */
    const generateAndAddImage = async (
        s: CharacterState,
        enrichment?: { wardrobe: string; personality: string }
    ): Promise<CharacterImage | null> => {
        const result = await reVisualizeCharacter(s, enrichment);
        if (!result?.dataUrl) {
            console.warn('Image generation returned empty result');
            return null;
        }
        const newImage = createCharacterImage(result.dataUrl, result.mediaId);
        // Attach a snapshot of the current state so we can restore on nav
        newImage.snapshot = {
            brief: s.initialBackstory,
            wardrobe: s.wardrobeSummary,
            personality: s.personalitySummary,
        };
        dispatch({ type: 'ADD_IMAGE', image: newImage });
        return newImage;
    };

    /**
     * Normalize raw feedback from the AI — ensure IDs and suggestions arrays.
     */
    const normalizeFeedback = (raw: Feedback[], prefix = 'f'): Feedback[] =>
        raw.map((f, idx) => ({
            ...f,
            id: f.id || `${prefix}-${Date.now()}-${idx}`,
            suggestions: f.suggestions || [],
        }));

    // --- Actions ---

    /**
     * Fetch feedback from the AI based on current state.
     */
    const fetchUpdate = useCallback(
        async (overrideState?: CharacterState) => {
            const s = overrideState || stateRef.current;
            setAnalyzing(true);
            setError(null);
            try {
                const update = await getCharacterUpdate(s);
                dispatch({ type: 'SET_FEEDBACK', feedback: normalizeFeedback(update.feedback || []) });
            } catch (err) {
                setError(err instanceof Error ? err.message : 'The executive is unavailable.');
            } finally {
                setAnalyzing(false);
            }
        },
        []
    );

    /**
     * Fetch wardrobe + psychology summaries.
     */
    const fetchSummaries = useCallback(
        async (overrideState?: CharacterState) => {
            const s = overrideState || stateRef.current;
            try {
                const summaries = await generateCharacterSummaries(s);
                dispatch({ type: 'SET_SUMMARIES', wardrobe: summaries.wardrobe, personality: summaries.personality });
            } catch (err) {
                console.warn('Summaries generation failed (non-critical):', err);
            }
        },
        []
    );

    /**
     * Adopt a feedback answer: store Q&A for later brief update,
     * remove the card, and auto-craft a prompt.
     */
    const pendingAnswersRef = useRef<{ insight: string; answer: string }[]>([]);

    const adoptAnswer = useCallback(
        (feedbackId: string, answer: string) => {
            const current = stateRef.current;
            const feedback = current.activeFeedback.find((f) => f.id === feedbackId);
            if (!feedback) return;

            // Toggle the answer in the multi-select array
            dispatch({ type: 'ANSWER_FEEDBACK', id: feedbackId, answer });

            // Track for prompt crafting
            const prev = feedback.answeredWith || [];
            const has = prev.includes(answer);
            if (has) {
                // Removing — remove from pending answers
                pendingAnswersRef.current = pendingAnswersRef.current.filter(
                    a => !(a.insight === feedback.insight && a.answer === answer)
                );
            } else {
                // Adding
                pendingAnswersRef.current.push({ insight: feedback.insight, answer });
            }
        },
        []
    );

    const resetAnswers = useCallback(() => {
        dispatch({ type: 'RESET_ANSWERS' });
        pendingAnswersRef.current = [];
    }, []);

    /**
     * Regenerate the current image — creates a new variant with the same state.
     */
    const regenerateImage = useCallback(async () => {
        const s = stateRef.current;
        if (s.imageHistory.length === 0) return;
        setVisualizing(true);
        try {
            const enrichment = s.wardrobeSummary && s.personalitySummary
                ? { wardrobe: s.wardrobeSummary, personality: s.personalitySummary }
                : undefined;
            await generateAndAddImage(s, enrichment);
        } catch (err) {
            console.error(err);
            setError('Image regeneration failed.');
        } finally {
            setVisualizing(false);
        }
    }, []);

    /**
     * Internal prompt crafter (ref-stable, callable from adoptAnswer).
     */
    const prepareImagePromptInternal = useCallback(async () => {
        const current = stateRef.current;
        // Allow crafting with brief or pending answers
        if (!current.initialBackstory.trim() && pendingAnswersRef.current.length === 0) return;

        setCraftingPrompt(true);
        setError(null);
        try {
            const recentChanges = [
                ...(current.highlightSegments || []),
                ...pendingAnswersRef.current.map(a => `${a.insight}: ${a.answer}`),
            ];
            const enrichment = current.wardrobeSummary && current.personalitySummary
                ? { wardrobe: current.wardrobeSummary, personality: current.personalitySummary }
                : undefined;

            const prompt = await craftImagePrompt(
                current.initialBackstory,
                recentChanges,
                enrichment
            );
            dispatch({ type: 'SET_IMAGE_PROMPT', prompt });
        } catch (err) {
            console.error('Failed to craft prompt:', err);
            setError('Failed to prepare image prompt.');
        } finally {
            setCraftingPrompt(false);
        }
    }, []);

    const prepareImagePrompt = prepareImagePromptInternal;

    /**
     * Update the pending image prompt text (user editing).
     */
    const setImagePrompt = useCallback((prompt: string) => {
        dispatch({ type: 'SET_IMAGE_PROMPT', prompt });
    }, []);

    /**
     * Confirm and generate the image using the pending prompt.
     * Brief updates are sequenced to prevent race conditions.
     */
    const confirmImageGeneration = useCallback(async () => {
        const current = stateRef.current;
        const prompt = current.pendingImagePrompt;
        if (!prompt) return;

        setVisualizing(true);
        dispatch({ type: 'CLEAR_IMAGE_PROMPT' });
        try {
            const currentImage = current.imageHistory[current.currentImageIndex];
            const result = await generateImageFromPrompt(
                prompt,
                currentImage?.mediaId
            );

            const latestState = stateRef.current;
            const newImage = createCharacterImage(result.dataUrl, result.mediaId, {
                brief: latestState.initialBackstory,
                wardrobe: latestState.wardrobeSummary,
                personality: latestState.personalitySummary,
            });
            dispatch({ type: 'ADD_IMAGE', image: newImage });

            // Commit pending answers to the brief first, then regenerate for image context.
            // Sequential to avoid race condition where the second call overwrites the first.
            const answers = pendingAnswersRef.current;
            let briefAfterAnswers = stateRef.current.initialBackstory;

            if (answers.length > 0) {
                try {
                    const { updatedBrief, highlightSegments } = await updateCharacterBrief(
                        briefAfterAnswers,
                        answers
                    );
                    dispatch({ type: 'UPDATE_BRIEF', brief: updatedBrief, highlights: highlightSegments });
                    briefAfterAnswers = updatedBrief;
                    pendingAnswersRef.current = [];
                } catch (err) {
                    console.error('Brief update failed:', err);
                }
            }

            // Now regenerate brief to reflect the new image (uses the already-updated brief)
            try {
                const { updatedBrief, highlightSegments: briefHighlights } = await updateCharacterBrief(
                    briefAfterAnswers,
                    [{ insight: 'Image update', answer: `The character image was regenerated with prompt: ${prompt}` }]
                );
                dispatch({ type: 'UPDATE_BRIEF', brief: updatedBrief, highlights: briefHighlights });
            } catch (err) {
                console.error('Brief regen after image failed:', err);
            }

            dispatch({ type: 'CLEAR_HIGHLIGHTS' });

            // Refresh feedback + summaries with updated state
            setAnalyzing(true);
            const nextState: CharacterState = {
                ...stateRef.current,
                highlightSegments: [],
            };
            try {
                await Promise.all([
                    fetchUpdate(nextState),
                    fetchSummaries(nextState),
                ]);
            } finally {
                setAnalyzing(false);
            }
        } catch (err) {
            console.error('Image generation failed:', err);
            setError('Image generation failed.');
        } finally {
            setVisualizing(false);
        }
    }, [fetchUpdate, fetchSummaries]);

    /**
     * Discard the pending image prompt.
     */
    const discardImagePrompt = useCallback(() => {
        dispatch({ type: 'CLEAR_IMAGE_PROMPT' });
    }, []);

    const regenerateFeedback = useCallback(
        async (questionId: string) => {
            setRegeneratingId(questionId);
            try {
                const current = stateRef.current;
                const otherFeedback = current.activeFeedback.filter((f) => f.id !== questionId);
                const newFeedback = await regenerateSingleFeedback(current, otherFeedback);
                newFeedback.id = `q-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
                newFeedback.category = newFeedback.category || 'style';
                newFeedback.suggestions = newFeedback.suggestions || [];
                newFeedback.insight = newFeedback.insight || '';
                dispatch({ type: 'REPLACE_FEEDBACK', oldId: questionId, newFeedback });
            } catch (err) {
                console.error('Feedback regeneration failed:', err);
                setError('Failed to regenerate feedback.');
            } finally {
                setRegeneratingId(null);
            }
        },
        []
    );

    const saveCurrentImage = useCallback(async () => {
        const current = stateRef.current;
        const img = current.imageHistory[current.currentImageIndex];
        if (img) {
            try {
                const base64 = img.base64.includes(',') ? img.base64.split(',')[1] : img.base64;
                await Flow.save({
                    base64,
                    mimeType: (img.mimeType || 'image/jpeg') as 'image/png' | 'image/jpeg',
                    name: `Character Revision ${current.currentImageIndex + 1}`,
                });
            } catch (err) {
                console.error('Save failed:', err);
            }
        }
    }, []);

    const setBackstory = useCallback((backstory: string) => {
        dispatch({ type: 'SET_BACKSTORY', backstory });
    }, []);

    const clearHighlights = useCallback(() => {
        dispatch({ type: 'CLEAR_HIGHLIGHTS' });
    }, []);

    const navImage = useCallback((index: number) => {
        dispatch({ type: 'NAV_IMAGE', index });
    }, []);

    const uploadImage = useCallback(async () => {
        try {
            const media = await Flow.media.select({ filter: 'image' });
            const dataUrl = `data:${media.mimeType};base64,${media.base64}`;
            const newImage: CharacterImage = {
                id: media.mediaId || Math.random().toString(36).substring(7),
                dataUrl,
                base64: media.base64,
                mimeType: media.mimeType,
                mediaId: media.mediaId,
                snapshot: {
                    brief: stateRef.current.initialBackstory,
                    wardrobe: stateRef.current.wardrobeSummary,
                    personality: stateRef.current.personalitySummary,
                },
            };
            dispatch({ type: 'ADD_IMAGE', image: newImage });
        } catch (err) {
            // User cancelled media picker
        }
    }, []);

    /**
     * Kickoff: fires summaries, image gen, AND feedback all in parallel.
     * Used on first "Develop" press.
     */
    const kickoffGuard = useRef(false);
    const kickoff = useCallback(async () => {
        if (kickoffGuard.current) return;
        kickoffGuard.current = true;

        const current = stateRef.current;
        // Allow starting with either a brief OR an uploaded image
        if (!current.initialBackstory.trim() && current.imageHistory.length === 0) return;

        setError(null);
        setAnalyzing(true);

        const hasUploadedImage = current.imageHistory.length > 0;

        try {
            if (hasUploadedImage) {
                // Has image already — generate summaries with image context, then feedback
                const [update, summaries] = await Promise.all([
                    getCharacterUpdate(current),
                    generateCharacterSummaries(current).catch((err) => {
                        console.warn('Summaries generation failed (non-critical):', err);
                        return null;
                    }),
                ]);

                dispatch({ type: 'SET_FEEDBACK', feedback: normalizeFeedback(update.feedback || []) });
                if (summaries) {
                    dispatch({ type: 'SET_SUMMARIES', wardrobe: summaries.wardrobe, personality: summaries.personality });
                }
            } else {
                // No image — summaries → image → feedback (sequential)
                // Show image loading state immediately
                setVisualizing(true);

                let enrichment: { wardrobe: string; personality: string } | undefined;
                try {
                    const summaries = await generateCharacterSummaries(current);
                    dispatch({ type: 'SET_SUMMARIES', wardrobe: summaries.wardrobe, personality: summaries.personality });
                    enrichment = summaries;
                } catch (err) {
                    console.warn('Pre-image summaries failed (non-critical):', err);
                }

                // Generate image — clear visualizing as soon as it appears
                const newImage = await generateAndAddImage(current, enrichment);
                setVisualizing(false);

                // Fetch feedback with the new image (non-blocking to the image display)
                if (newImage) {
                    const latestState = stateRef.current;
                    const stateForFeedback: CharacterState = {
                        ...latestState,
                        imageHistory: [...latestState.imageHistory.slice(0, -1), newImage],
                        currentImageIndex: latestState.imageHistory.length - 1,
                    };
                    const update = await getCharacterUpdate(stateForFeedback);
                    dispatch({ type: 'SET_FEEDBACK', feedback: normalizeFeedback(update.feedback || []) });
                } else {
                    await fetchUpdate();
                }
            }
        } catch (err) {
            console.error('Kickoff failed:', err);
            setError(err instanceof Error ? err.message : 'Failed to initialize character.');
        } finally {
            setAnalyzing(false);
            kickoffGuard.current = false;
        }
    }, [fetchUpdate]);

    const startOver = useCallback(async () => {
        try {
            const media = await Flow.media.select({ filter: 'image' });
            dispatch({ type: 'RESET' });
            kickoffGuard.current = false;
            pendingAnswersRef.current = [];
            setAnalyzing(false);
            setVisualizing(false);
            setCraftingPrompt(false);
            setError(null);
            const dataUrl = `data:${media.mimeType};base64,${media.base64}`;
            const newImage: CharacterImage = {
                id: media.mediaId || Math.random().toString(36).substring(7),
                dataUrl,
                base64: media.base64,
                mimeType: media.mimeType,
                mediaId: media.mediaId,
                snapshot: { brief: '', wardrobe: '', personality: '' },
            };
            dispatch({ type: 'ADD_IMAGE', image: newImage });
        } catch (err) {
            // User cancelled media picker
        }
    }, []);


    const actions: CharacterActions = {
        adoptAnswer,
        resetAnswers,
        regenerateFeedback,
        prepareImagePrompt,
        setImagePrompt,
        confirmImageGeneration,
        discardImagePrompt,
        saveCurrentImage,
        setBackstory,
        clearHighlights,
        navImage,
        uploadImage,
        startOver,
        kickoff,
        regenerateImage,
    };

    return {
        state,
        analyzing,
        visualizing,
        adoptingId,
        regeneratingId,
        craftingPrompt,
        error,
        actions,
    };
}

import { Flow } from "flow-sdk";
import { DevelopmentUpdate, CharacterState, Feedback, CharacterSummaries } from "../types";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Attempts to parse JSON from AI output, stripping markdown fences and
 * trying to extract a JSON object even if surrounded by prose.
 */
function safeJsonParse<T>(raw: string): T {
    // Strip markdown code fences
    let cleaned = raw;
    while (cleaned.includes('```json')) cleaned = cleaned.split('```json').join('');
    while (cleaned.includes('```')) cleaned = cleaned.split('```').join('');
    cleaned = cleaned.trim();

    try {
        return JSON.parse(cleaned);
    } catch {
        // Attempt to find the first { ... } or [ ... ] block
        const objStart = cleaned.indexOf('{');
        const objEnd = cleaned.lastIndexOf('}');
        const arrStart = cleaned.indexOf('[');
        const arrEnd = cleaned.lastIndexOf(']');
        const objMatch = objStart !== -1 && objEnd > objStart ? cleaned.slice(objStart, objEnd + 1) : null;
        const arrMatch = arrStart !== -1 && arrEnd > arrStart ? cleaned.slice(arrStart, arrEnd + 1) : null;
        const candidate = objMatch || arrMatch;
        if (candidate) {
            return JSON.parse(candidate);
        }
        throw new Error("Could not extract valid JSON from AI response.");
    }
}

/**
 * Simple retry wrapper — one retry with a short delay.
 */
async function withRetry<T>(fn: () => Promise<T>, retries = 1, delayMs = 1500): Promise<T> {
    try {
        return await fn();
    } catch (err) {
        if (retries <= 0) throw err;
        console.warn(`⚠️ Retrying after error:`, err);
        await new Promise(r => setTimeout(r, delayMs));
        return withRetry(fn, retries - 1, delayMs * 2);
    }
}

/**
 * Build an images array for Flow.generate.text() from a CharacterImage.
 */
function buildFlowImages(img: { base64: string; mimeType: string }): { base64: string; mimeType: string }[] {
    const base64 = img.base64.includes(',') ? img.base64.split(',')[1] : img.base64;
    return [{ base64, mimeType: img.mimeType }];
}

